
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hjs_pbe_sol_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hjs_pbe_sol", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.262265257902859e+00, -3.199217365570510e+00, -3.110886703290524e+00, -2.988560393200074e+00, -2.821955129993587e+00, -2.600414466394578e+00, -2.315785295999123e+00, -1.967741862977488e+00, -1.571439174347014e+00, -1.163119223363249e+00, -7.891377589296077e-01, -5.735609054535871e-01, -5.084323821004009e-01, -4.136808161507883e-01, -2.952918590993537e-01, -1.873003086710093e-01, -1.082326133006783e-01, -4.682028974072398e-02, -1.079521973304640e-02, -1.204886150358069e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


